import React, { useState } from 'react';
import { predictStroke } from '../services/api';

const DEFAULTS = {
  gender: 'Male',
  age: '',
  hypertension: '0',
  heart_disease: '0',
  ever_married: 'Yes',
  work_type: 'Private',
  Residence_type: 'Urban',
  avg_glucose_level: '',
  bmi: '',
  smoking_status: 'never smoked',
};

export default function PredictionForm({ onResult }) {
  const [form, setForm]     = useState(DEFAULTS);
  const [loading, setLoading] = useState(false);
  const [error, setError]   = useState('');

  const handle = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const payload = {
        ...form,
        age:               parseFloat(form.age),
        hypertension:      parseInt(form.hypertension),
        heart_disease:     parseInt(form.heart_disease),
        avg_glucose_level: parseFloat(form.avg_glucose_level),
        bmi:               parseFloat(form.bmi),
      };
      const result = await predictStroke(payload);
      onResult(result, payload);
    } catch (err) {
      setError(err.message || 'Failed to connect to server.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <form className="prediction-form" onSubmit={handleSubmit}>
      <div className="form-grid">

        <div className="form-group">
          <label>Gender</label>
          <select name="gender" value={form.gender} onChange={handle}>
            <option>Male</option>
            <option>Female</option>
            <option>Other</option>
          </select>
        </div>

        <div className="form-group">
          <label>Age</label>
          <input type="number" name="age" value={form.age} onChange={handle}
            required min="1" max="120" placeholder="e.g. 45" />
        </div>

        <div className="form-group">
          <label>Hypertension</label>
          <select name="hypertension" value={form.hypertension} onChange={handle}>
            <option value="0">No</option>
            <option value="1">Yes</option>
          </select>
        </div>

        <div className="form-group">
          <label>Heart Disease</label>
          <select name="heart_disease" value={form.heart_disease} onChange={handle}>
            <option value="0">No</option>
            <option value="1">Yes</option>
          </select>
        </div>

        <div className="form-group">
          <label>Ever Married</label>
          <select name="ever_married" value={form.ever_married} onChange={handle}>
            <option>Yes</option>
            <option>No</option>
          </select>
        </div>

        <div className="form-group">
          <label>Work Type</label>
          <select name="work_type" value={form.work_type} onChange={handle}>
            <option>Private</option>
            <option>Self-employed</option>
            <option>Govt_job</option>
            <option>children</option>
            <option>Never_worked</option>
          </select>
        </div>

        <div className="form-group">
          <label>Residence Type</label>
          <select name="Residence_type" value={form.Residence_type} onChange={handle}>
            <option>Urban</option>
            <option>Rural</option>
          </select>
        </div>

        <div className="form-group">
          <label>Avg Glucose Level (mg/dL)</label>
          <input type="number" name="avg_glucose_level" value={form.avg_glucose_level}
            onChange={handle} required min="0" step="0.01" placeholder="e.g. 100.5" />
        </div>

        <div className="form-group">
          <label>BMI</label>
          <input type="number" name="bmi" value={form.bmi} onChange={handle}
            required min="1" step="0.1" placeholder="e.g. 25.0" />
        </div>

        <div className="form-group">
          <label>Smoking Status</label>
          <select name="smoking_status" value={form.smoking_status} onChange={handle}>
            <option>never smoked</option>
            <option>formerly smoked</option>
            <option>smokes</option>
            <option>Unknown</option>
          </select>
        </div>

      </div>

      {error && <p className="error-msg">{error}</p>}

      <button type="submit" className="submit-btn" disabled={loading}>
        {loading ? 'Analyzing...' : 'Predict Stroke Risk'}
      </button>
    </form>
  );
}
